		httpStatus = undefined;
		if (run) run.stopReason = message.stopReason;
	});

	pi.on("agent_settled", (event, ctx) => {
		finishRun(ctx.cwd, event.aborted ? "aborted" : stopStatus(run?.stopReason));
	});

