            reads.append(str(a.get("path")))
        if r.get("recordType")=="tool_end" and r.get("isError"): errs+=1
        if r.get("recordType")=="message" and r.get("usage"):
            u=r["usage"]; c=u.get("cost") or {}
            cost += c.get("total",0) if isinstance(c,dict) else c
            for k,v in u.items():
                if isinstance(v,(int,float)): toks[k]+=v
    print(run, "calls=",len(calls),"cost=",round(cost,6),"in=",toks.get("input"),"out=",toks.get("output"),"cacheRead=",toks.get("cacheRead"),"errs=",errs)
    print("   reads:",reads)
    print("   tools:",dict(collections.Counter(n for n,_ in calls)))
